r.append(R(7342064,"ग्रीन मसाला फ़िश करी","यह व्यंजन कई तरह की मछलियों के साथ अच्छा बनता है और रात के खाने के लिए सबसे सेहतमंद विकल्प है।","2","316 ग्राम",
[("सॉस के लिए","75 ग्राम ताज़ा धनिया, मोटा कटा हुआ"),("सॉस के लिए","10 ग्राम ताज़ा पुदीना, मोटा कटा हुआ"),("सॉस के लिए","30 ग्राम अजमोद (पार्सले), मोटा कटा हुआ"),("सॉस के लिए","1 नीबू (लाइम) का रस"),("सॉस के लिए","150 मिलीलीटर पानी"),("सॉस के लिए","2 छोटे चम्मच रेपसीड तेल"),("सॉस के लिए","1 प्याज़, बारीक कटा हुआ"),("सॉस के लिए","1 लाल शिमला मिर्च, पतली कटी हुई"),("सॉस के लिए","1 मिर्च, बारीक कटी हुई"),("सॉस के लिए","4 सेमी अदरक, बारीक कटा हुआ"),("सॉस के लिए","2 लहसुन की फांकें, कुचली हुई"),("सॉस के लिए","2 छोटे चम्मच हल्का करी पाउडर"),("सॉस के लिए","100 ग्राम सैल्मन, बड़े टुकड़ों में"),("सॉस के लिए","100 ग्राम कॉड, बड़े टुकड़ों में")],
["धनिया, पुदीना, अजमोद, नीबू का रस और पानी को एक साथ ब्लेंड करें और एक तरफ़ रख दें।","पैन में तेल डालें, फिर प्याज़ और लाल शिमला मिर्च डालें। 3-4 मिनट तक नरम होने तक गरम करें।","मिर्च, अदरक और लहसुन डालें, और 1-2 मिनट चलाएँ। करी पाउडर छिड़कें और एक मिनट और अच्छी तरह मिलाएँ।","मछली को पैन में डालें, फिर उसे सारे मसालों में लपेटें, ध्यान रखें कि मछली के टुकड़े टूटें नहीं।","हरी सॉस डालें, हल्का उबाल लाएँ, फिर आँच कम करें और बीच-बीच में चलाते हुए 3-4 मिनट तक पकाएँ जब तक कि मछली अंदर तक पक न जाए। धनिये की टहनी और नीबू की फांकों के साथ परोसें।"],
["यह सॉस चिकन के साथ या शाकाहारी संस्करण के लिए टोफू के साथ बढ़िया लगती है।","यह व्यंजन झींगे या किसी भी मछली के साथ अच्छा बनता है।",FV(1)]))
r.append(R(7346125,"वेजिटेबल रैप","साबुत गेहूँ का एक रैप जो हल्का, ले जाने में आसान और सेहतमंद है।","1","266 ग्राम",
["1 बड़ा साबुत गेहूँ का टॉर्टिया रैप",("नमकीन भरावन के लिए","1 बड़ा चम्मच हमस"),("नमकीन भरावन के लिए","1 छोटी गाजर, पीलर से फीतों जैसी कटी हुई"),("नमकीन भरावन के लिए","एक चौथाई लाल प्याज़, पतला कटा हुआ"),("नमकीन भरावन के लिए","एक चौथाई पीली शिमला मिर्च, मोटी कटी हुई"),("नमकीन भरावन के लिए","छोटी मुट्ठी भर अल्फाल्फा"),("नमकीन भरावन के लिए","मुट्ठी भर लेट्यूस, बारीक कटा हुआ")],
["टॉर्टिया को सूखे फ्राइंग पैन में हर तरफ़ 1 मिनट गरम करें (इससे वह ज़्यादा लचीला हो जाता है)। इसके बाद, इसे बोर्ड पर रखें और हमस को नीचे के बाएँ चौथाई हिस्से पर फैलाएँ, रैप के किनारों पर 2 सेमी का हाशिया छोड़ दें।","गाजर, प्याज़, पीली शिमला मिर्च, अल्फाल्फा और लेट्यूस को हमस के ऊपर रखें।","टॉर्टिया को नीचे से ऊपर की ओर कसकर लपेटें, जब एक तिहाई ऊपर पहुँच जाएँ तो किनारों को अंदर मोड़ दें।","ग्रीसप्रूफ़ पेपर या फ़ॉइल में लपेटें और सिरों को मरोड़ दें।"],
["साबुत गेहूँ के टॉर्टिया में फ़ाइबर ज़्यादा होता है और यह आपको ज़्यादा देर तक पेट भरा महसूस कराता है। साबुत अनाज हृदय और पाचन तंत्र के स्वास्थ्य के लिए फ़ायदेमंद होते हैं।","साबुत गेहूँ के टॉर्टिया रसोई में रखने के लिए एक काम की चीज़ हैं। ये बहुत पतले पिज़्ज़ा बेस के रूप में अच्छे लगते हैं।","अगर आपको अल्फाल्फा न मिले, तो आप इसकी जगह वॉटरक्रेस, रॉकेट (अरुगुला) या अतिरिक्त लेट्यूस इस्तेमाल कर सकते हैं।",FV(2)]))
r.append(R(7347873,"मेवों वाले चॉकलेट ट्रफ़ल","पार्टी में परोसने के लिए बिल्कुल सही, ये आसानी से तैयार होने वाले ट्रफ़ल उपहार के रूप में भी बढ़िया लगते हैं।","28","17 ग्राम",
["340 ग्राम मेजूल खजूर, गुठलियाँ निकाली हुई","80 ग्राम कच्चे बादाम","25 ग्राम बिना चीनी वाला कोको पाउडर, साथ में लपेटने के लिए थोड़ा और","2 बड़े चम्मच सूरजमुखी का तेल","1 छोटा चम्मच वनीला एक्सट्रैक्ट"],
["सारी सामग्री को फ़ूड प्रोसेसर में डालें और 2-3 मिनट तक या चिपचिपा आटे का गोला बनने तक प्रोसेस करें।","मिश्रण के 2 छोटे चम्मच की गोलियाँ बनाएँ और अतिरिक्त कोको पाउडर में लपेटकर परत चढ़ाएँ। जब तक सारा मिश्रण इस्तेमाल न हो जाए, दोहराएँ।"],
["आप अपने ट्रफ़ल पर भुने तिल, मुलैठी का पाउडर, सूखा नारियल, कटे मेवे, माचा ग्रीन टी पाउडर की परत चढ़ाकर देख सकते हैं, या उन्हें सादा छोड़ सकते हैं। स्वाद भी कई तरह के हो सकते हैं – संतरा, कॉफ़ी, पिपरमिंट, या यहाँ तक कि रम भी बढ़िया विकल्प हैं।","ये ट्रफ़ल कभी-कभार के मीठे व्यंजन के रूप में सुझाए जाते हैं, लेकिन बाँटने या उपहार देने के लिए बिल्कुल सही हैं।"]))
r.append(R(7348447,"हिरण के मांस और क्रैनबेरी का कैसरोल","सामान्य रोस्ट या क्रिसमस डिनर के एक स्वादिष्ट, उत्सवी विकल्प के लिए इसे आज़माएँ।","6","229 ग्राम",
["50 ग्राम का पैकेट सूखी क्रैनबेरी","3 बड़े चम्मच पोर्ट","3 बड़े चम्मच कॉर्नफ़्लोर","चुटकी भर पिसा ऑलस्पाइस","1 छोटा चम्मच पिसी अदरक (सोंठ)","ताज़ी पिसी काली मिर्च","900 ग्राम हिरण के मांस का स्टेक, टुकड़ों में कटा हुआ","1 बड़ा चम्मच रेपसीड तेल","1 दालचीनी की छड़ी","18 छोटे बटन प्याज़, छिले हुए","1 संतरे का ज़ेस्ट और रस","2 बड़े चम्मच क्रैनबेरी सॉस","450 मिलीलीटर कम नमक वाला बीफ़/वेजिटेबल स्टॉक"],
["सूखी क्रैनबेरी को पोर्ट के साथ छोटे कटोरे में डालें और 30 मिनट तक मैरिनेट होने दें। इस बीच, कॉर्नफ़्लोर, ऑलस्पाइस और अदरक को बड़े फ़ूड बैग में डालें, अच्छी तरह मसाला डालें और मिलाने के लिए हिलाएँ।","हिरण के मांस को बैग में डालें और आटे के मिश्रण में लपेटने के लिए हिलाएँ। एक बड़े कैसरोल डिश में तेल गरम करें, दालचीनी की छड़ी और प्याज़ डालें और 3 मिनट तक भूनें।","मांस और बैग में बचा कोई भी आटा डालें और 3-4 मिनट तक भूरा होने तक भूनें।","बची हुई सामग्री को मिलाएँ, कैसरोल डिश में डालें, उबाल लाएँ, ढककर लगभग 1 घंटा 20 मिनट तक बहुत हल्की आँच पर पकाएँ जब तक कि मांस नरम न हो जाए।"],
["अच्छे कसाई या सुपरमार्केट हिरण के मांस के कई हिस्से बेचेंगे। इस रेसिपी के लिए स्ट्यूइंग स्टेक का उपयोग करें जो आमतौर पर पहले से टुकड़ों में कटा बिकता है। इसे पकने में थोड़ा ज़्यादा समय लगता है लेकिन यह स्टेक जितना ही स्वादिष्ट और बहुत सस्ता होता है। ज़्यादातर रेसिपी में हिरण के मांस को बीफ़ के कम वसा वाले विकल्प के रूप में इस्तेमाल किया जा सकता है।","अगर आपके पास पोर्ट नहीं है, तो उसकी जगह रेड वाइन इस्तेमाल करें, या अगर आप अल्कोहल का उपयोग नहीं करना चाहते तो बस 3 बड़े चम्मच पानी या अतिरिक्त स्टॉक इस्तेमाल करें।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। फ्रिज में या माइक्रोवेव में पिघलाएँ और पूरी तरह भाप निकलने तक अच्छी तरह दोबारा गरम करें।",FV(0)]))
r.append(R(7349349,"सैल्मन फ़िशकेक","इस कुरकुरे, जड़ी-बूटी वाले फ़िशकेक में सैल्मन बहुत स्वादिष्ट लगती है।","2","398 ग्राम",
["350 ग्राम आलू, छीले और कटे हुए","300 ग्राम ताज़ा सैल्मन, उबालकर रेशों में तोड़ी हुई, या अगर चाहें तो डिब्बाबंद","2 हरी प्याज़ (स्प्रिंग अनियन), कटी हुई","2 एंकोवी फ़िलेट, कटे हुए","मुट्ठी भर ताज़ी जड़ी-बूटियाँ (जैसे अजमोद और सोआ), कटी हुई","1 बड़ा चम्मच हल्का मेयोनेज़","ताज़ी पिसी काली मिर्च","छिड़कने के लिए मैदा","1 अंडा, फेंटा हुआ","2 स्लाइस ग्रेनरी ब्रेड, ब्रेडक्रम्ब्स के रूप में","2 छोटे चम्मच वनस्पति तेल","परोसने के लिए नीबू की फांकें"],
["आलुओं को 10-15 मिनट तक नरम होने तक उबालें, फिर मैश करें।","सैल्मन, आलू, हरी प्याज़, एंकोवी, जड़ी-बूटियाँ और मेयोनेज़ को मोटा मैश करें और अच्छी तरह मसाला डालें","4 टिक्कियाँ बनाएँ और लगभग 30 मिनट के लिए फ्रिज में रखें।","हर फ़िशकेक पर मैदा छिड़कें, फिर अंडे में डुबोएँ और ब्रेडक्रम्ब्स में लपेटें।","फ़िशकेक को तेल लगी बेकिंग शीट पर रखें और थोड़ा तेल छिड़कें।","मध्यम ग्रिल पर हर तरफ़ 2-3 मिनट तक पकाएँ। नीबू की फांकों के साथ परोसें।"],
["सैल्मन, केकड़ा और झींगे जैसी मछलियों के मिश्रण का उपयोग करके देखें।","ज़्यादा फ़ाइबर वाले, थोड़े घने फ़िशकेक बनाने के लिए आप साबुत गेहूँ की ब्रेड इस्तेमाल कर सकते हैं।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। हर फ़िशकेक के बीच ग्रीसप्रूफ़ पेपर रखकर अलग-अलग लपेटे हुए हिस्सों में फ्रीज़ करें। फ्रिज में, या माइक्रोवेव में पिघलाएँ और पूरी तरह भाप निकलने तक अच्छी तरह गरम करें।",FV(0)]))
r.append(R(7353647,"केजरी","नाश्ते के इस क्लासिक का यह संस्करण स्मोक्ड हैडॉक की जगह ताज़ी सैल्मन और स्मोक्ड पेपरिका से बनाया गया है, क्योंकि स्मोक्ड हैडॉक में नमक ज़्यादा होता है।","4","114 ग्राम",
["300 ग्राम बासमती चावल","2 ढेर वाले छोटे चम्मच हल्का-मध्यम करी पेस्ट (या पाउडर)","1 ढेर वाला छोटा चम्मच हल्की (डुल्से) स्मोक्ड पेपरिका","4 अंडे","2 छोटे चम्मच सूरजमुखी का तेल","1 लीक, बारीक कटा हुआ","1 लाल शिमला मिर्च, बारीक कटी हुई","300 ग्राम बिना त्वचा और बिना हड्डी की सैल्मन, मोटे तौर पर 2-3 सेमी के टुकड़ों में कटी हुई","1 नीबू का रस","1 बड़ा चम्मच कम वसा वाला दही","मुट्ठी भर बारीक कटा धनिया, साथ में परोसने के लिए एक टहनी","1 नीबू, फांकों में कटा हुआ"],
["बासमती चावल को पानी में धोएँ और 700 मिलीलीटर उबलते पानी (1 भाग चावल से 2 भाग पानी) के साथ पैन में डालें। 1 ढेर वाला छोटा चम्मच करी पेस्ट और सारी स्मोक्ड पेपरिका डालें, मिलाएँ, वापस उबाल लाएँ, ढक दें, आँच कम करें और 10-12 मिनट तक हल्की आँच पर पकाएँ। आँच बंद करें और ढक्कन लगाकर 3 मिनट के लिए रखा रहने दें। तब सारा पानी सोख लिया जाना चाहिए।","इस बीच, 4 अंडों को 5 मिनट तक उबालें, ठंडे पानी में डालें, छीलें और चार भागों में काटें।","फ्राइंग पैन में सूरजमुखी का तेल गरम करें और लीक तथा लाल शिमला मिर्च डालें। नियमित रूप से चलाते हुए 5-7 मिनट तक नरम होने तक पकाएँ।","बचे हुए करी पेस्ट को लीक और शिमला मिर्च के साथ मिलाएँ और सैल्मन डालें। 3-4 मिनट पकाएँ और एक तरफ़ रख दें।","चावल में नीबू का रस, दही और धनिया डालें और अच्छी तरह मिलाएँ।","सब्ज़ी और सैल्मन के मिश्रण को गरम चावल में धीरे से मिलाएँ और ऊपर से अंडे के चौथाई हिस्से, नीबू की फांकें और धनिये की एक टहनी रखें।"],
["अगर आप अंडे हटा दें और मछली की जगह मशरूम या स्मोक्ड टोफू इस्तेमाल करें तो केजरी आसानी से वीगन बनाई जा सकती है।","आप कॉड या हैडॉक जैसी कोई भी सफ़ेद मछली इस्तेमाल कर सकते हैं, या कुछ झींगे भी डाल सकते हैं। अगर आपके पास धनिया नहीं है तो अजमोद अच्छा लगता है।","जल्दी तैयार होने वाले व्यंजन के लिए, आप पहले से पके चावल इस्तेमाल कर सकते हैं और सब्ज़ियों तथा सैल्मन में पेपरिका डाल सकते हैं। अंडे एक दिन पहले उबालकर फ्रिज में रखे जा सकते हैं।",FV(0)]))
r.append(R(7355331,"फ़िश करी","एक मसालेदार और सुगंधित पारंपरिक बंगाली करी जो सलाद के साथ परोसने पर बढ़िया लगती है।","2","445 ग्राम",
["600 ग्राम सी ब्रीम (300 ग्राम मछली का गूदा)","1 ढेर वाला छोटा चम्मच + 1 छोटा चम्मच पिसी हल्दी","1 बड़ा चम्मच सूरजमुखी का तेल","2 छोटे चम्मच पाँच फोरन (बंगाली साबुत मसालों का मिश्रण)","5 हरी इलायची की फलियाँ, कुचली हुई","2 बड़े प्याज़, पतले कटे हुए","2 सेमी ताज़ा अदरक, बारीक कद्दूकस किया हुआ","4 लहसुन की फांकें, कुचली हुई","1-2 हरी मिर्च, कटी हुई","1 छोटा चम्मच पिसा धनिया","1 छोटा चम्मच पिसा जीरा","आधा छोटा चम्मच लाल मिर्च पाउडर","2 तेज पत्ते","150 ग्राम आलू, छीले और कटे हुए","2 टमाटर, बारीक कटे हुए","1 बड़ा चम्मच ताज़ा कटा धनिया"],
["मछली पर 1 ढेर वाला छोटा चम्मच हल्दी लगाएँ और 2 मिनट के लिए रखा रहने दें।","सॉसपैन में तेल गरम करें और मछली डालें। हर तरफ़ 1 मिनट पकाएँ, पैन से निकालें और किचन पेपर पर रखें।","पाँच फोरन के मसाले और इलायची की फलियाँ पैन में डालें और नियमित रूप से चलाते हुए 1 मिनट तक भूनें।","प्याज़ डालें और नियमित रूप से चलाते हुए 4 मिनट तक पकाएँ।","अदरक, लहसुन और मिर्च डालें और एक मिनट और चलाएँ।","बची हुई 1 छोटा चम्मच हल्दी, धनिया, जीरा और लाल मिर्च पाउडर, तेज पत्ते और आलू डालें और 2 मिनट चलाएँ।","टमाटर और 250 मिलीलीटर पानी डालें, उबाल लाएँ, ढक दें, आँच कम करें और 10-12 मिनट तक हल्की आँच पर पकाएँ जब तक कि आलू बस पक न जाएँ।","मछली डालें, ढक्कन वापस लगाएँ और 6-8 मिनट तक हल्की आँच पर पकाएँ जब तक कि मछली अंदर तक पक न जाए।","धनिया छिड़कें और परोसें।"],
["यह ज़्यादातर मछलियों के साथ अच्छी बनती है, अगर आपको मछली के कांटों की चिंता है तो सैल्मन, कॉड, मॉन्कफ़िश के टुकड़े या बड़े झींगे इस्तेमाल करें।","अपना पाँच फोरन बनाने के लिए, काली सरसों, जीरा, सौंफ़, मेथी और कलौंजी के बीज बराबर मात्रा में मिलाएँ।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। फ्रिज में पिघलाएँ और पूरी तरह भाप निकलने तक अच्छी तरह दोबारा गरम करें।",FV(1)]))
r.append(R(7356133,"ट्रे में बेक्ड सैल्मन और सब्ज़ियाँ","एक साथ बेक किया गया यह स्वादिष्ट व्यंजन परिवार के रात के खाने के लिए आदर्श है।","4","349 ग्राम",
["300 ग्राम का पैकेट हरी बीन्स","8 हरी प्याज़ (स्प्रिंग अनियन), कटी हुई","150 ग्राम जमे हुए मटर (पिघलाए हुए)","1 लाल शिमला मिर्च, पतली कटी हुई","16 चेरी टमाटर","4 सैल्मन स्टेक, त्वचा के साथ और बिना हड्डी के (4 x 125 ग्राम)","3 बड़े चम्मच पानी","आधे नीबू का रस","परोसने के लिए नीबू की फांकें"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें।","हरी बीन्स को उबलते पानी में 4 मिनट तक ब्लांच करें और पानी निकाल दें।","हरी बीन्स, हरी प्याज़, मटर, लाल शिमला मिर्च और चेरी टमाटर को ओवन-प्रूफ़ डिश में फैलाएँ।","सैल्मन को ऊपर रखें, त्वचा वाली तरफ़ ऊपर करके, और नीबू का रस और पानी छिड़कें। फ़ॉइल से ढक दें।","20 मिनट तक बेक करें, फिर जाँचें कि मछली अंदर तक पक गई है या नहीं और ज़रूरत हो तो 5 मिनट और बेक करें (आपके स्टेक की मोटाई के अनुसार)।","नीबू की फांकों के साथ परोसें।"],
["यह कॉड, हैडॉक या कोलि जैसे दूसरे मछली के स्टेक के साथ भी अच्छा बनता है।","आप इसे पहले से तैयार करके बेक करने के लिए तैयार होने तक कुछ घंटों के लिए फ्रिज में रख सकते हैं।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। जल्दी ठंडा करें। फ्रिज में पिघलाएँ और पूरी तरह भाप निकलने तक अच्छी तरह दोबारा गरम करें।",FV(2)]))
r.append(R(7356307,"चिकन और सोयाबीन सलाद","जिन दिनों आपके पास समय कम हो, उन दिनों के लिए प्रोटीन से भरपूर दोपहर का भोजन।","1","452 ग्राम",
["1 छोटा चिकन ब्रेस्ट (125 ग्राम)","2 नीबू की फांकें","150 मिलीलीटर उबलता पानी","50 ग्राम जमी हुई सोयाबीन (एडामामे), पिघलाई हुई","मुट्ठी भर मिले-जुले सलाद के पत्ते","2 हरी प्याज़ (स्प्रिंग अनियन), कटी हुई","4 सेमी खीरा, कटा हुआ","1 बड़ा टमाटर, कटा हुआ","आधा पैकेट क्रेस","1 बड़ा चम्मच 0% वसा वाला दही","1 छोटा चम्मच ताहिनी (तिल का पेस्ट)","आधा छोटा चम्मच तिल","एक अच्छी चुटकी काली मिर्च"],
["चिकन पर नीबू की 1 फांक निचोड़ें। चिकन को पैन में रखें और बस ढकने के लिए उबलता पानी डालें। ढक्कन लगाएँ और 5-6 मिनट तक हल्की आँच पर पकाएँ।","आँच बंद करें और ढक्कन लगाकर 5 मिनट और रहने दें।","इस बीच, सोयाबीन, सलाद के पत्ते और हरी प्याज़ अपने डिब्बे में डालें। इसके बाद, खीरा, टमाटर और क्रेस डालें।","एक छोटे कटोरे में दही और ताहिनी मिलाएँ, और रिसाव-रोधी ढक्कन वाले छोटे डिब्बे में रखें।","चिकन का पानी निकालें, ठंडा होने दें और फिर काट लें।","चिकन को सलाद के ऊपर सजाएँ। नीबू की दूसरी फांक, थोड़े तिल और चुटकी भर काली मिर्च के साथ परोसें। अगर यह सलाद कहीं ले जाकर खा रहे हैं तो ढक्कन लगाएँ और ताहिनी ड्रेसिंग के साथ पैक करें।"],
[FV(2)]))
r.append(R(7358851,"भुना स्क्वैश और कुरकुरे छोले वाला चिकन सलाद","यह ताज़ा, स्वादिष्ट सलाद एक बिल्कुल सही सेहतमंद दोपहर के भोजन का विकल्प बनता है। मूल रूप से Balance पत्रिका में प्रकाशित।","4","373 ग्राम",
["1 बटरनट स्क्वैश","सूरजमुखी के तेल की 1 कैलोरी वाली स्प्रे की 16 बार स्प्रे","400 ग्राम का डिब्बा छोले, धोए हुए","2 छोटे चम्मच पिसा जीरा","20 ग्राम कद्दू के बीज","75 ग्राम का धुली हुई रॉकेट (अरुगुला) का पैकेट","छोटी मुट्ठी भर ताज़ा धनिया","200 ग्राम भुना हुआ चिकन ब्रेस्ट, रेशों में तोड़ा हुआ","1/2 छोटा लाल प्याज़, फांकों में कटा हुआ","100 मिलीलीटर कम वसा वाला सादा दही","1 बड़ा चम्मच ताहिनी","1 बड़ा चम्मच नीबू का रस","1 छोटी लहसुन की फांक, कुचली हुई","1 बड़ा चम्मच कटा हुआ ताज़ा पुदीना"],
["ओवन को 190°C/375°F/गैस मार्क 5 पर पहले से गरम करें। स्क्वैश को 8 फांकों में काटें, बीज फेंक दें।","रोस्टिंग टिन में रखें, तेल की स्प्रे करें, जीरा छिड़कें और 10 मिनट तक भूनें। छोले और प्याज़ डालें और बीच-बीच में उछालते हुए 20 मिनट तक भूनें। बीज डालें और 5 मिनट पकाएँ, फिर ठंडा होने दें।","रॉकेट, धनिया, चिकन, प्याज़, स्क्वैश और छोले को प्लेट में सजाएँ।","पुदीने को छोड़कर बची हुई सामग्री को एक साथ ब्लिट्ज़ (तेज़ी से ब्लेंड) करें। पुदीना मिलाएँ, ड्रेसिंग छिड़कें और परोसें।"],
[FV(1)]))
r.append(R(7359452,"चिकन कैसरोल","कैसरोल में दालें डालने से अतिरिक्त प्रोटीन और फ़ाइबर मिलता है।","4","346 ग्राम",
["4 छोटे बिना त्वचा के चिकन ब्रेस्ट (500 ग्राम)","1 बड़ा प्याज़, कटा हुआ","2 लहसुन की फांकें, कुचली हुई","2 हरी शिमला मिर्च, बीज निकाली हुई और कटी हुई","2 बड़े चम्मच ताज़ा मार्जोरम या आधा बड़ा चम्मच सूखा","1 x 400 ग्राम का डिब्बा कटे हुए टमाटर","150 मिलीलीटर कम नमक वाला चिकन स्टॉक","1 x 420 ग्राम का डिब्बा बोरलोटी बीन्स, छनी और धोई हुई","2 बड़े चम्मच टमाटर प्यूरी","ताज़ी पिसी काली मिर्च"],
["एक बड़े नॉन-स्टिक सॉसपैन को गरम करें और चिकन ब्रेस्ट को हर तरफ़ भूरा होने तक भूनें। अगर चिकन पैन में चिपक रहा हो तो आप पैन में थोड़ा पानी डाल सकते हैं।","प्याज़, लहसुन और शिमला मिर्च डालें और 2-3 मिनट तक भूनते रहें।","कटे टमाटर, चिकन स्टॉक, बीन्स, टमाटर प्यूरी, ताज़ी पिसी काली मिर्च और जड़ी-बूटियाँ डालें।","अच्छी तरह चलाएँ, उबाल लाएँ, ढककर 40-45 मिनट तक हल्की आँच पर पकाएँ।"],
["यह व्यंजन टर्की के साथ भी अच्छा बनता है।","अगर आप चाहें तो बोरलोटी बीन्स की जगह मिली-जुली बीन्स या छोले इस्तेमाल कर सकते हैं।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। फ्रिज में पिघलाएँ और पूरी तरह भाप निकलने तक दोबारा गरम करें।",FV(3)]))
r.append(R(7359781,"शकरकंद क्रूटॉन के साथ कॉर्न चाउडर","स्मोकी भुनी शकरकंद के छोटे टुकड़ों से सजा क्रीमी कॉर्न और सब्ज़ियों का सूप।","2","510 ग्राम",
[("क्रूटॉन के लिए","1 शकरकंद (150 ग्राम), 1 सेमी के चौकोर टुकड़ों में कटी हुई"),("क्रूटॉन के लिए","1 छोटा चम्मच तेल"),("क्रूटॉन के लिए","1 ढेर वाला छोटा चम्मच स्मोक्ड पेपरिका"),("चाउडर के लिए","1 छोटा चम्मच तेल"),("चाउडर के लिए","1 बड़ा प्याज़, बारीक कटा हुआ"),("चाउडर के लिए","1 गाजर, चौकोर कटी हुई"),("चाउडर के लिए","1 डंठल सेलरी, पतली कटी हुई"),("चाउडर के लिए","180 ग्राम जमा स्वीटकॉर्न"),("चाउडर के लिए","एक अच्छी चुटकी सफ़ेद मिर्च"),("चाउडर के लिए","1 बड़ा चम्मच मैदा"),("चाउडर के लिए","1 कम नमक वाला वेजिटेबल स्टॉक क्यूब, 250 मिलीलीटर पानी में घुला हुआ"),("चाउडर के लिए","300 मिलीलीटर स्किम्ड दूध"),("चाउडर के लिए","1 बड़ा चम्मच ताज़ा चाइव्स, कटी हुई"),("चाउडर के लिए","एक अच्छी मात्रा में पिसी काली मिर्च")],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। पहले शकरकंद के क्रूटॉन बनाएँ। एक बड़े कटोरे में शकरकंद के टुकड़ों पर 1 छोटा चम्मच तेल छिड़कें और उन्हें समान रूप से लपेटने के लिए उलट-पलट करें। स्मोक्ड पेपरिका छिड़कें, फिर से उलट-पलट करें और बेकिंग शीट पर फैलाएँ। नियमित रूप से पलटते हुए 25-35 मिनट तक बेक करें।","इस बीच, चाउडर बनाएँ। एक बड़े सॉसपैन में जैतून का तेल गरम करें और प्याज़ को 3-4 मिनट तक भूनें। गाजर, सेलरी, स्वीटकॉर्न और सफ़ेद मिर्च डालें। 3 मिनट चलाएँ और मैदा छिड़कें।","धीरे-धीरे वेजिटेबल स्टॉक मिलाएँ जब तक यह गाढ़ा न हो जाए। ढक दें फिर आँच कम करें और 5 मिनट तक हल्की आँच पर पकाएँ।","दो मिनट तक धीरे-धीरे दूध मिलाएँ और वापस उबाल पर लाएँ।","चाउडर को कटोरों में डालें और ऊपर से थोड़ी कटी हुई चाइव्स और थोड़ी ताज़ी पिसी काली मिर्च छिड़कें। शकरकंद के क्रूटॉन, ताज़ी चाइव्स और काली मिर्च से सजाएँ।"],
["अगर आपका चाउडर थोड़ा ज़्यादा गाढ़ा हो जाए, तो बस धीरे-धीरे थोड़ा और दूध मिला दें।","कॉर्न सीफ़ूड चाउडर बनाने के लिए आप ताज़ी सैल्मन के टुकड़े या कुछ बड़े झींगे डाल सकते हैं।","फ्रीज़ करने के निर्देश: क्रूटॉन को अलग से फ्रीज़ करें। सूप को माइक्रोवेव में या बहुत धीमी आँच पर पूरी तरह भाप निकलने तक गरम होने तक पिघलाएँ।",FV(3)]))
